test("Core inherited-record replay bound records its exact range", async () => {
	const record = await readCoreInheritedRecordReplayBound();
	assert.equal(record.schemaVersion, 1);
	assert.equal(record.milestone
		, "core-inherited-record-replay-bound-source-v1");
	assert.equal(record.predecessorCommit
		, coreInheritedRecordReplayBoundPredecessor);
	assert.equal(record.implementationCommit
		, coreInheritedRecordReplayBoundImplementation);
	assert.deepEqual(record.updates.map(update => update.path)
		, coreInheritedRecordReplayBoundImplementationPaths);
	assert.deepEqual(record.historyAdditions.map(addition => addition.path)
		, coreInheritedRecordReplayBoundHistoryAdditions);
	assert.deepEqual(record.integrationUpdates.map(update => update.path)
		, coreInheritedRecordReplayBoundIntegrationPaths);
	assert.equal(git(["rev-parse"
		, `${coreInheritedRecordReplayBoundImplementation}^`]).trim()
	, coreInheritedRecordReplayBoundPredecessor);
	assert.deepEqual(git(["diff", "--name-only", "--diff-filter=M"
		, coreInheritedRecordReplayBoundPredecessor
		, coreInheritedRecordReplayBoundImplementation])
		.trim().split("\n").sort()
	, [...coreInheritedRecordReplayBoundImplementationPaths].sort());
});

test("Core inherited-record replay bound reverses every transition", async () => {
	const record = await readCoreInheritedRecordReplayBound();
	for(const update of [...record.updates, ...record.integrationUpdates])
	{
		const integration = record.integrationUpdates.includes(update);
		const current = integration
			? await sourceAtFinHistoryRecordSource(
				coreInheritedRecordReplayBoundHistoryPath, update.path
				, update.currentSha256
				, beforeCoreInheritedRecordReplayBoundSource
			)
			: await sourceAtFinHistoryRecord(
				coreInheritedRecordReplayBoundHistoryPath, update.path
				, beforeCoreInheritedRecordReplayBoundSource
			);
		const base = integration
			? coreInheritedRecordReplayBoundImplementation
			: coreInheritedRecordReplayBoundPredecessor;
		const previous = git(["show", `${base}:${update.path}`]);
		assert.equal(reverseCoreInheritedRecordReplayBoundUpdate(
			current, update), previous, update.path);
		assert.equal(beforeFinRefinementSource(
			update.path, current, update.previousSha256), previous, update.path);
		assert.ok(finRefinementNormalizationPaths.includes(update.path));
	}
	for(const addition of record.historyAdditions)
		assert.equal(sha256(await sourceAtFinHistoryRecordSource(
			coreInheritedRecordReplayBoundHistoryPath
			, addition.path, addition.currentSha256
		)), addition.currentSha256, addition.path);
});

test("Core inherited-record replay bound rejects altered transitions", async () => {
	const update = (await readCoreInheritedRecordReplayBound()).updates[0];
	const current = await sourceAtFinHistoryRecord(
		coreInheritedRecordReplayBoundHistoryPath, update.path
		, beforeCoreInheritedRecordReplayBoundSource
	);
	for(const forged of [{ ...update, currentSha256: "0".repeat(64) }
		, { ...update, previousSha256: "0".repeat(64) }
		, { ...update, path: "unrelated.mjs" }
		, { ...update, edits: [] }
		, { ...update, edits: [...update.edits, update.edits[0]] }])
		assert.throws(() => reverseCoreInheritedRecordReplayBoundUpdate(
			current, forged));
	assert.equal(beforeCoreInheritedRecordReplayBoundSource(
		update.path, current + "unknown"), current + "unknown");
});

test("Core inherited-record replay-bound writer refuses another checkout", async t => {
	const root = await mkdtemp(join(
		tmpdir(), "lean-core-inherited-replay-history-guard-"));
	t.after(() => rm(root, { recursive: true }));
	const result = spawnSync(process.execPath, [resolve(
		"scripts/update-core-inherited-record-replay-bound-source-history.mjs"
	)], { cwd: root, encoding: "utf8", timeout: 15_000 });
	assert.notEqual(result.status, 0);
	assert.equal(result.stdout, "");
	assert.deepEqual(await readdir(root), []);
});

